W=/private/tmp/claude-501/-Users-junaidatique--claude-spares-spare-x2tKTE/df021aa3-23ff-4dbf-a7c9-3e227d3a8b25/scratchpad/review/blind/work
cat > $W/compact.py <<'EOF'
import sys
sys.path.insert(0, "/private/tmp/claude-501/-Users-junaidatique--claude-spares-spare-x2tKTE/df021aa3-23ff-4dbf-a7c9-3e227d3a8b25/scratchpad/scripts")
from pcxml import parse
X="/Users/junaidatique/work/infinite-lambda-test/external/flowline-pwc-demo/FLOWLINE_DEMO_JAFFLESHOP.xml"
r=parse(X)
def port(p):
    a=p.a
    s=f"  L{p.start} {a.get('PORTTYPE','')[:14]:14} {a.get('NAME')}: {a.get('DATATYPE')}({a.get('PRECISION')},{a.get('SCALE')})"
    for k in ("GROUP","REF_FIELD","ISSORTKEY","SORTDIRECTION","DEFAULTVALUE","EXPRESSION","EXPRESSIONTYPE"):
        v=a.get(k)
        if v not in (None,""):
            if k=="ISSORTKEY" and v=="NO": continue
            if k=="SORTDIRECTION" and a.get("ISSORTKEY")!="YES": continue
            if k=="EXPRESSION" and v==a.get("NAME"): continue
            if k=="EXPRESSIONTYPE" and v=="GENERAL": continue
            s+=f" {k}={v!r}"
    other={k:v for k,v in a.items() if k not in ("PORTTYPE","NAME","DATATYPE","PRECISION","SCALE","GROUP","REF_FIELD","ISSORTKEY","SORTDIRECTION","DEFAULTVALUE","EXPRESSION","EXPRESSIONTYPE","DESCRIPTION","PICTURETEXT","BUSINESSNAME")}
    if other: s+=" "+repr(other)
    return s
def attrs(n,tag="TABLEATTRIBUTE"):
    out=[]
    for c in n.kids(tag):
        v=c.get("VALUE","")
        if v!="": out.append(f"{c.get('NAME')}={v!r}@L{c.start}")
    return out
for m in r.iter("MAPPING"):
    print(f"=== MAPPING {m.get('NAME')} L{m.start}-{m.end}")
    for t in m.kids("TRANSFORMATION"):
        print(f"T {t.get('NAME')} [{t.get('TYPE')}] L{t.start}-{t.end} reusable={t.get('REUSABLE')}")
        for c in t.children:
            if c.tag=="TRANSFORMFIELD": print(port(c))
            elif c.tag=="GROUP": print(f"  L{c.start} GROUP {c.a}")
            elif c.tag in ("TABLEATTRIBUTE",): pass
            else: print(f"  L{c.start} {c.tag} {c.a}")
        a=attrs(t)
        if a: print("  ATTR: "+"; ".join(a))
        for c in t.kids("INITPROP"): print(f"  L{c.start} INITPROP {c.a}")
    for i in m.kids("INSTANCE"):
        extra=" ".join(f"{k}={v}" for k,v in i.a.items() if k not in ("DESCRIPTION","NAME","TRANSFORMATION_NAME","TRANSFORMATION_TYPE","TYPE"))
        print(f"I L{i.start} {i.get('NAME')} <- {i.get('TRANSFORMATION_NAME')} [{i.get('TRANSFORMATION_TYPE')}] {extra}")
        for c in i.children:
            if c.tag=="TABLEATTRIBUTE":
                if c.get("VALUE","")!="": print(f"   L{c.start} ATTR {c.get('NAME')}={c.get('VALUE')!r}")
            elif c.tag=="ASSOCIATED_SOURCE_INSTANCE": print(f"   L{c.start} ASSOC {c.get('NAME')}")
            else: print(f"   L{c.start} {c.tag} {c.a}")
    for c in m.kids("CONNECTOR"):
        print(f"C L{c.start} {c.get('FROMINSTANCE')}.{c.get('FROMFIELD')} -> {c.get('TOINSTANCE')}.{c.get('TOFIELD')}")
    for c in m.children:
        if c.tag not in ("TRANSFORMATION","INSTANCE","CONNECTOR"):
            print(f"O L{c.start}-{c.end} {c.tag} {c.a}")
            for d in c.children: print(f"   L{d.start} {d.tag} {d.a}")
EOF
